mapper.sql:
WHERE p.status = 'PUBLISHED'
  AND p.deleted_at IS NULL
  AND u.status <> 'SUSPENDED'

    AND (
        LOCATE(BINARY #{keyword}, BINARY p.title) > 0
        OR LOCATE(BINARY #{keyword}, BINARY COALESCE(p.summary, '')) > 0
        OR LOCATE(BINARY #{keyword}, BINARY p.content) > 0
    )


    AND category.category_id = #{categoryId}


    AND rr.region = #{region}



    AND EXISTS (
        SELECT 1
          FROM post_tags pt
          JOIN tags t ON t.tag_id = pt.tag_id
         WHERE pt.post_id = p.post_id
           AND BINARY REPLACE(t.normalized_name, ' ', '') = BINARY #{tag}
    )



    AND rr.distance_km >= #{minDistance}


    AND rr.distance_km <= #{maxDistance}
